fn cta_button(
  testid: String,
  label: String,
  extra_class: String,
) -> Element(Msg) {
  html.a(
    [
      tid(testid),
      attribute.href("/signup"),
      class(
        "inline-block bg-amber text-white font-semibold rounded-lg hover:bg-amber/90 transition-colors focus:outline-none focus:ring-2 focus:ring-amber focus:ring-offset-2 "
        <> extra_class,
      ),
    ],
    [html.text(label)],
  )
}

